tool.command:
ln -s $input_ligand_path ./input_ligand_path.$input_ligand_path.ext; ln -s $input_receptor_path ./input_receptor_path.$input_receptor_path.ext; #if $input_box_path: ln -s $input_box_path ./input_box_path.$input_box_path.ext; #end if #if $input_autobox_path: ln -s $input_autobox_path ./input_autobox_path.$input_autobox_path.ext; #end if #if $config_json: ln -s $config_json ./config_json.$config_json.ext; #end if
gnina_run
#if $config_json: --config ./config_json.$config_json.ext #end if
--input_ligand_path ./input_ligand_path.$input_ligand_path.ext --input_receptor_path ./input_receptor_path.$input_receptor_path.ext #if $input_box_path: --input_box_path ./input_box_path.$input_box_path.ext #end if #if $input_autobox_path: --input_autobox_path ./input_autobox_path.$input_autobox_path.ext #end if --output_sdf_path $outname_output_sdf_path #if $outname_output_summary_path: --output_summary_path $outname_output_summary_path #end if #if $outname_output_log_path: --output_log_path $outname_output_log_path #end if ;
mv $outname_output_sdf_path $output_sdf_path; if test -f $outname_output_summary_path; then mv $outname_output_summary_path $output_summary_path; fi; if test -f $outname_output_log_path; then mv $outname_output_log_path $output_log_path; fi;
